let language = 'zh';
try {
  if (localStorage.getItem('v3cell.language') === 'en') language = 'en';
} catch { /* The switch also works when storage is unavailable. */ }

function t(key, values = {}) {
  return messages[key][language === 'en' ? 1 : 0].replace(/\{(\w+)\}/g, (_, name) => values[name]);
}

function localize(root) {
  for (const [field, attribute] of [['i18n', null], ['i18nLabel', 'aria-label'], ['i18nAlt', 'alt'], ['i18nContent', 'content']]) {
    const selector = field.replace(/[A-Z]/g, c => '-' + c.toLowerCase());
    for (const element of root.querySelectorAll('[data-' + selector + ']')) {
      const value = t(element.dataset[field]);
      if (attribute) element.setAttribute(attribute, value);
      else element.textContent = value;
    }
  }
}
